if(!function_exists('sk1390_home_config')){
function sk1390_db(): ?PDO {try{return function_exists('db')?db():null;}catch(Throwable $e){return null;}}
function sk1390_setting(string $key,string $default=''): string {static $c=[];if(array_key_exists($key,$c))return $c[$key];$pdo=sk1390_db();if(!$pdo)return $c[$key]=$default;try{$q=$pdo->prepare('SELECT setting_value FROM settings WHERE setting_key=? LIMIT 1');$q->execute([$key]);$v=$q->fetchColumn();return $c[$key]=$v===false?$default:(string)$v;}catch(Throwable $e){return $c[$key]=$default;}}
function sk1390_bool(string $key,bool $default=true): bool {return in_array(strtolower(trim(sk1390_setting($key,$default?'1':'0'))),['1','true','yes','on','enabled'],true);}
function sk1390_int(string $key,int $default,int $min,int $max): int {$v=sk1390_setting($key,(string)$default);$n=is_numeric($v)?(int)$v:$default;return max($min,min($max,$n));}
function sk1390_tid(): int {try{if(function_exists('sk1300_tid')){$t=(int)sk1300_tid();if($t>0)return $t;}}catch(Throwable $e){}try{$u=function_exists('current_user')?current_user():null;if(is_array($u)){foreach(['tenant_id','city_id'] as $k)if(isset($u[$k])&&(int)$u[$k]>0)return (int)$u[$k];}}catch(Throwable $e){}return 1;}
function sk1390_table(string $table): bool {static $c=[];if(isset($c[$table]))return $c[$table];$pdo=sk1390_db();if(!$pdo)return $c[$table]=false;try{$q=$pdo->prepare('SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=?');$q->execute([$table]);return $c[$table]=(bool)$q->fetchColumn();}catch(Throwable $e){return $c[$table]=false;}}
function sk1390_cut(string $s,int $max=180): string {$s=trim(preg_replace('~\s+~u',' ',$s)??$s);return function_exists('mb_substr')?mb_substr($s,0,$max,'UTF-8'):substr($s,0,$max);}
function sk1390_allowed_url(string $url): bool {if($url===''||$url[0]!=='/')return false;try{if(function_exists('sk1300_nav_url_allowed'))return (bool)sk1300_nav_url_allowed($url);}catch(Throwable $e){}return true;}
function sk1390_home_config(): array {return ['version'=>'13.9.0','enabled'=>sk1390_bool('homepage_smart_search_enabled',true),'minChars'=>sk1390_int('homepage_smart_search_min_chars',2,1,4),'maxSuggestions'=>sk1390_int('homepage_smart_search_max_suggestions',10,5,20),'recentEnabled'=>sk1390_bool('homepage_smart_search_recent_enabled',true),'endpoint'=>'/api/homepage-smart-search-v1390.php'];}
function sk1390_push(array &$out,array &$seen,string $type,string $title,string $subtitle,string $url,string $icon='⌕'): void {$url=trim($url);$title=sk1390_cut($title,140);if($title===''||!sk1390_allowed_url($url)||isset($seen[$url]))return;$seen[$url]=1;$out[]=['type'=>$type,'title'=>$title,'subtitle'=>sk1390_cut($subtitle,180),'url'=>$url,'icon'=>sk1390_cut($icon,8)];}
function sk1390_route_suggestions(string $q,array &$out,array &$seen): void {$needle=strtolower($q);$routes=[
 ['Service','Book a local service','/services.php','⚡',['electrician','plumber','tailor','repair','service','ac','fridge','carpenter','painter','cleaning','mechanic','solar','cctv']],
 ['Classifieds','Buy & sell locally','/classifieds.php','◈',['buy','sell','mobile','bike','car','classified','used','marketplace']],
 ['Education','Courses & local learning','/education-network.php','▤',['course','education','teacher','student','learn','class','academy','school']],
 ['City Map','Find verified places nearby','/city-map.php','⌖',['map','near','location','business','shop','hospital','bank','restaurant']],
 ['Property','Browse local property','/property.php','⌂',['property','house','plot','rent','sale','shop']],
 ['Jobs','Local jobs & opportunities','/jobs.php','▣',['job','vacancy','work','hiring']]
 ];foreach($routes as [$type,$sub,$url,$icon,$keys]){foreach($keys as $k){if($needle===''||str_contains($needle,$k)||str_contains($k,$needle)){sk1390_push($out,$seen,$type,$type,$sub,$url,$icon);break;}}}}
function sk1390_search(string $query): array {$cfg=sk1390_home_config();$q=sk1390_cut($query,120);$out=[];$seen=[];$limit=(int)$cfg['maxSuggestions'];if(!$cfg['enabled'])return ['ok'=>true,'enabled'=>false,'items'=>[]];if($q===''){sk1390_route_suggestions('',$out,$seen);return ['ok'=>true,'enabled'=>true,'items'=>array_slice($out,0,$limit),'query'=>''];}if((function_exists('mb_strlen')?mb_strlen($q,'UTF-8'):strlen($q))<(int)$cfg['minChars'])return ['ok'=>true,'enabled'=>true,'items'=>[],'query'=>$q];$pdo=sk1390_db();$tid=sk1390_tid();$like='%'.$q.'%';
 // Verified/map-ready city places from the existing bounded discovery engine.
 try{if(!function_exists('sk1350cd_payload')){$f=__DIR__.'/city_discovery_v1350.php';if(is_file($f))require_once $f;}if(function_exists('sk1350cd_payload')){$p=sk1350cd_payload(['q'=>$q,'limit'=>8]);foreach(array_slice((array)($p['items']??[]),0,4) as $r){if(!is_array($r))continue;$url=(string)($r['url']??'');if($url==='')$url='/city-map.php?q='.rawurlencode((string)($r['label']??''));sk1390_push($out,$seen,'Place',(string)($r['label']??''),(string)($r['category']??'Verified local place'),$url,'⌖');}}}catch(Throwable $e){}
 if($pdo){
  // Approved provider services only.
  if(sk1390_table('service_offerings_v1380')&&sk1390_table('service_provider_profiles_v1380')&&sk1390_table('service_categories_v1380')){try{$s=$pdo->prepare("SELECT s.id,s.title,s.provider_id,c.name category_name,COALESCE(NULLIF(p.business_name,''),p.display_name) provider_name FROM service_offerings_v1380 s JOIN service_provider_profiles_v1380 p ON p.id=s.provider_id AND p.tenant_id=s.tenant_id JOIN service_categories_v1380 c ON c.id=s.category_id WHERE s.tenant_id=? AND s.active=1 AND p.status='approved' AND p.public_profile=1 AND (s.title LIKE ? OR c.name LIKE ? OR p.business_name LIKE ? OR p.display_name LIKE ?) ORDER BY s.featured_until>NOW() DESC,p.rating_avg DESC,s.id DESC LIMIT 4");$s->execute([$tid,$like,$like,$like,$like]);foreach($s->fetchAll(PDO::FETCH_ASSOC)?:[] as $r)sk1390_push($out,$seen,'Service',(string)$r['title'],trim((string)$r['category_name'].' · '.(string)$r['provider_name']),'/request-service.php?provider='.(int)$r['provider_id'].'&service='.(int)$r['id'],'⚡');}catch(Throwable $e){}}
  // Active moderated classifieds only; no seller private data is returned.
  if(sk1390_table('classified_ads_v1370')&&sk1390_table('classified_categories_v1370')){try{$s=$pdo->prepare("SELECT a.title,a.slug,a.price,a.price_type,a.area,c.name category_name FROM classified_ads_v1370 a JOIN classified_categories_v1370 c ON c.id=a.category_id WHERE a.tenant_id=? AND a.status='active' AND a.moderation_status='approved' AND (a.expires_at IS NULL OR a.expires_at>NOW()) AND (a.title LIKE ? OR c.name LIKE ? OR a.area LIKE ?) ORDER BY a.featured_until>NOW() DESC,a.bump_at DESC,a.id DESC LIMIT 4");$s->execute([$tid,$like,$like,$like]);foreach($s->fetchAll(PDO::FETCH_ASSOC)?:[] as $r){$price=(string)$r['price_type']==='free'?'Free':((string)$r['price_type']==='contact'?'Contact for price':'PKR '.number_format((float)$r['price'],0));sk1390_push($out,$seen,'Classified',(string)$r['title'],trim((string)$r['category_name'].' · '.$price.' · '.(string)$r['area']),'/classified.php?ad='.rawurlencode((string)$r['slug']),'◈');}}catch(Throwable $e){}}
  // Public LMS courses only.
  if(sk1390_table('lms_courses_v1360')){try{$s=$pdo->prepare("SELECT title,slug,category,level,price,currency FROM lms_courses_v1360 WHERE tenant_id=? AND status='published' AND visibility<>'private' AND (title LIKE ? OR category LIKE ? OR level LIKE ?) ORDER BY updated_at DESC,id DESC LIMIT 4");$s->execute([$tid,$like,$like,$like]);foreach($s->fetchAll(PDO::FETCH_ASSOC)?:[] as $r){$price=(float)$r['price']>0?((string)$r['currency'].' '.number_format((float)$r['price'],0)):'Free';sk1390_push($out,$seen,'Course',(string)$r['title'],trim((string)$r['category'].' · '.(string)$r['level'].' · '.$price),'/education-network.php?course='.rawurlencode((string)$r['slug']),'▤');}}catch(Throwable $e){}}
 }
 sk1390_route_suggestions($q,$out,$seen);return ['ok'=>true,'enabled'=>true,'query'=>$q,'items'=>array_slice($out,0,$limit),'count'=>min(count($out),$limit),'ranking'=>'live published records first; no fabricated popularity'];}
